// v661 PRICE SLIDER (Kendall, 28 Oct 2026: 'host the price slider') - the public Najma price-range page, built in naj-market-pulse
// apps/najma-price-slider/index.html and copied here verbatim. It reads only the public Esri scene and buildings view, anonymously:
// no key, no sign-in, no Azimuth data. Regenerate this file from that index.html; do not edit the page here.
export const PRICE_SLIDER_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n  <meta name=\"robots\" content=\"noindex, nofollow\" />\n  <title>Najma Price Slider</title>\n  <!-- ArcGIS Maps SDK for JavaScript 5.1, pinned (same as apps/najma-brief-3d): one module script loads the core ($arcgis.import),\n       the map components and Calcite. Anonymous: the scene and the buildings view are public, so no API key and no sign-in. -->\n  <link rel=\"stylesheet\" href=\"https://js.arcgis.com/5.1/esri/themes/light/main.css\" />\n  <script type=\"module\" src=\"https://js.arcgis.com/5.1/\"></script>\n  <style>\n    :root { --gold: #e0a412; --ink: #1d2a33; --muted: #5b6b75; --line: #d9dee2; --panel: #ffffff; }\n    html, body { margin: 0; height: 100%; font-family: \"Avenir Next\", \"Segoe UI\", system-ui, sans-serif; color: var(--ink); background: #eef1f3; }\n    #app { position: fixed; inset: 0; display: grid; grid-template-columns: 340px 1fr; grid-template-rows: 1fr auto; }\n    #panel { grid-row: 1; grid-column: 1; overflow-y: auto; background: var(--panel); border-right: 1px solid var(--line); padding: 14px 16px; box-sizing: border-box; }\n    #sceneWrap { grid-row: 1; grid-column: 2; position: relative; min-height: 0; }\n    arcgis-scene { position: absolute; inset: 0; }\n    footer { grid-row: 2; grid-column: 1 / 3; font-size: 11px; line-height: 1.4; color: var(--muted); background: #f7f8f9; border-top: 1px solid var(--line); padding: 6px 12px; }\n    h1 { font-size: 18px; margin: 0 0 2px; } h1 span { color: var(--gold); }\n    .sub { font-size: 12px; color: var(--muted); margin: 0 0 12px; }\n    .ctl { margin: 0 0 14px; }\n    .lbl { font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: .04em; color: var(--muted); margin-bottom: 6px; display: block; }\n    calcite-segmented-control { width: 100%; }\n    #range { font-size: 20px; font-weight: 700; margin: 2px 0 4px; }\n    #limits { font-size: 11px; color: var(--muted); display: flex; justify-content: space-between; }\n    #count { font-size: 22px; font-weight: 700; } #count small { font-size: 13px; font-weight: 500; color: var(--muted); }\n    .note { font-size: 11px; color: var(--muted); margin-top: 4px; }\n    .row { display: flex; align-items: center; gap: 8px; font-size: 13px; }\n    .legend { display: flex; gap: 12px; font-size: 12px; color: var(--muted); margin-top: 8px; }\n    .sw { display: inline-block; width: 12px; height: 12px; border-radius: 2px; vertical-align: -2px; margin-right: 4px; }\n    #status { font-size: 11px; color: #a23; min-height: 14px; }\n    @media (max-width: 760px) {\n      #app { grid-template-columns: 1fr; grid-template-rows: 52vh 1fr auto; }\n      #sceneWrap { grid-row: 1; grid-column: 1; }\n      #panel { grid-row: 2; grid-column: 1; border-right: 0; border-top: 1px solid var(--line); }\n      footer { grid-row: 3; grid-column: 1; font-size: 10px; max-height: 14vh; overflow-y: auto; }\n    }\n  </style>\n</head>\n<body>\n<div id=\"app\">\n  <aside id=\"panel\" aria-label=\"Price filter\">\n    <h1>Najma <span>Price Slider</span></h1>\n    <p class=\"sub\">Dubai buildings by median price per bedroom size. Research use only.</p>\n\n    <div class=\"ctl\">\n      <span class=\"lbl\">Price</span>\n      <calcite-segmented-control id=\"mode\" scale=\"m\" width=\"full\">\n        <calcite-segmented-control-item value=\"sale\" checked>Sale</calcite-segmented-control-item>\n        <calcite-segmented-control-item value=\"rent\">Annual rent</calcite-segmented-control-item>\n      </calcite-segmented-control>\n    </div>\n\n    <div class=\"ctl\">\n      <span class=\"lbl\">Bedrooms</span>\n      <calcite-segmented-control id=\"bed\" scale=\"m\" width=\"full\">\n        <calcite-segmented-control-item value=\"0\">Studio</calcite-segmented-control-item>\n        <calcite-segmented-control-item value=\"1\" checked>1</calcite-segmented-control-item>\n        <calcite-segmented-control-item value=\"2\">2</calcite-segmented-control-item>\n        <calcite-segmented-control-item value=\"3\">3</calcite-segmented-control-item>\n        <calcite-segmented-control-item value=\"4\">4+</calcite-segmented-control-item>\n      </calcite-segmented-control>\n    </div>\n\n    <div class=\"ctl\">\n      <span class=\"lbl\" id=\"rangeLbl\">Median sale price</span>\n      <div id=\"range\">…</div>\n      <calcite-slider id=\"slider\" min=\"0\" max=\"1000\" min-value=\"0\" max-value=\"1000\" step=\"1\" label-text=\"Price range\" disabled></calcite-slider>\n      <div id=\"limits\"><span id=\"limLo\"></span><span id=\"limHi\"></span></div>\n      <div class=\"note\">Slider ends = the 1st and 99th percentile of this field (log scale). A thumb left at an end leaves that side open.</div>\n    </div>\n\n    <div class=\"ctl\">\n      <label class=\"row\"><calcite-switch id=\"own\" checked></calcite-switch> Only buildings with their own price</label>\n      <div class=\"note\">On: the figure is the building's or project's own median (basis building or project). Off: district and Dubai-wide fallbacks are included too.</div>\n    </div>\n\n    <div class=\"ctl\">\n      <span class=\"lbl\">Districts</span>\n      <calcite-combobox id=\"districts\" selection-mode=\"multiple\" placeholder=\"All districts\" label=\"Districts\" scale=\"m\" max-items=\"8\"></calcite-combobox>\n    </div>\n\n    <div class=\"ctl\">\n      <div id=\"count\">… <small>buildings match</small></div>\n      <div class=\"legend\"><span><i class=\"sw\" style=\"background:var(--gold)\"></i>in range</span><span><i class=\"sw\" style=\"background:#c9ced2\"></i>other buildings (faded)</span></div>\n      <calcite-button id=\"zoom\" appearance=\"outline\" scale=\"s\" icon-start=\"zoom-to-object\" style=\"margin-top:8px\">Zoom to matches</calcite-button>\n      <div id=\"status\" role=\"status\"></div>\n    </div>\n  </aside>\n\n  <div id=\"sceneWrap\">\n    <arcgis-scene id=\"scene\" item-id=\"9bc1d8dcc06f43d99105b0e5a38308e0\"></arcgis-scene>\n  </div>\n\n  <footer>\n    Research use only. Map data: roads, paths, grass and parks from OpenStreetMap contributors (ODbL); water from Overture Maps (ODbL). Tree layout and 3D roads are illustrative.\n    Facade textures: Esri CityEngine bundled assets (used under Esri clearance). Sale and rent figures: DLD registered sales and Ejari lettings via Dubai Pulse. © OpenStreetMap contributors, Overture Maps Foundation; Esri.\n  </footer>\n</div>\n\n<script type=\"module\">\nconst VIEW_URL = \"https://services8.arcgis.com/X5OoNWyMULMQeWqf/arcgis/rest/services/najma_brief_public_buildings_v3/FeatureServer/0\";\nconst CARRIER_ID = \"najma_city_buildings_grey\";\nconst CONTEXT_IDS = [\"najma_buildings_known_height\", \"najma_buildings_placeholder_height\"];\nconst FACADE_IDS = [\"najma_city_facades_3d_w\", \"najma_city_facades_3d_e\"];\nconst UNITS = [\"units_studio\", \"units_1\", \"units_2\", \"units_3\", \"units_4plus\"];\nconst BEDNAME = [\"Studio\", \"1-bed\", \"2-bed\", \"3-bed\", \"4+ bed\"];\nconst OWN_BASIS = \"('building','project')\";\nconst STEPS = 1000;\n\nconst $ = (id) => document.getElementById(id);\nconst S = { mode: \"sale\", bed: 1, own: true, districts: [], p1: null, p99: null, lo: 0, hi: STEPS, count: null, statsCalls: 0, countCalls: 0, errors: [] };\nwindow.__ps = S;   // test hook (read-only state for the javascript check)\n\nconst [FeatureLayer, reactiveUtils] = await $arcgis.import([\"@arcgis/core/layers/FeatureLayer.js\", \"@arcgis/core/core/reactiveUtils.js\"]);\n\n// A layer used only for statistics and counts: never added to the map, so no definitionExpression is ANDed into its queries.\nconst statsLayer = new FeatureLayer({ url: VIEW_URL });\n\nconst priceField = () => `${S.mode}_median_aed_${S.bed}`;\nconst basisField = () => `${S.mode}_basis_${S.bed}`;\nfunction baseWhere() {\n  const u = UNITS[S.bed], p = priceField();\n  let w = `dup_status IS NULL AND (${u} IS NULL OR ${u} > 0) AND ${p} IS NOT NULL AND ${p} > 0`;\n  if (S.own) w += ` AND ${basisField()} IN ${OWN_BASIS}`;\n  if (S.districts.length) w += ` AND district_slug IN (${S.districts.map((d) => `'${d.replace(/'/g, \"''\")}'`).join(\",\")})`;\n  return w;\n}\n// Log scale between P1 and P99; a thumb at an end leaves that side open.\nconst toAed = (pos) => Math.exp(Math.log(S.p1) + (Math.log(S.p99) - Math.log(S.p1)) * pos / STEPS);\nfunction niceRound(v) { const m = Math.pow(10, Math.floor(Math.log10(v)) - 1); return Math.round(v / m) * m; }\nfunction bounds() {\n  return { lo: S.lo <= 0 ? null : niceRound(toAed(S.lo)), hi: S.hi >= STEPS ? null : niceRound(toAed(S.hi)) };\n}\nfunction fullWhere() {\n  const b = bounds(), p = priceField();\n  let w = baseWhere();\n  if (b.lo != null) w += ` AND ${p} >= ${b.lo}`;\n  if (b.hi != null) w += ` AND ${p} <= ${b.hi}`;\n  return w;\n}\nfunction fmt(v) {\n  if (v >= 1e6) return \"AED \" + (v / 1e6).toFixed(v >= 1e7 ? 1 : 2).replace(/\\.?0+$/, \"\") + \"M\";\n  if (v >= 1e3) return \"AED \" + Math.round(v / 1e3) + \"k\";\n  return \"AED \" + Math.round(v);\n}\nfunction renderRange() {\n  if (S.p1 == null) { $(\"range\").textContent = \"No figures for this choice\"; return; }\n  const b = bounds();\n  // Open ends read \"under P1\" / \"P99 and above\" so nothing outside P1-P99 is silently dropped.\n  const lo = b.lo == null ? \"any\" : fmt(b.lo);\n  const hi = b.hi == null ? \"any\" : fmt(b.hi);\n  let txt;\n  if (b.lo == null && b.hi == null) txt = \"Any price\";\n  else if (b.lo == null) txt = `AED 0 to ${hi}`;\n  else if (b.hi == null) txt = `${lo} and above`;\n  else txt = `${lo} to ${hi}`;\n  $(\"range\").textContent = txt;\n  $(\"limLo\").textContent = \"P1 \" + fmt(S.p1);\n  $(\"limHi\").textContent = \"P99 \" + fmt(S.p99);\n  $(\"rangeLbl\").textContent = `Median ${S.mode === \"sale\" ? \"sale price\" : \"annual rent\"}, ${BEDNAME[S.bed]}`;\n}\n\nlet highlight, sceneEl, view;\n\nlet statsSeq = 0;\nasync function loadStats() {\n  S.statsCalls++;\n  const my = ++statsSeq;\n  $(\"count\").innerHTML = `… <small>updating</small>`;\n  const p = priceField();\n  const res = await statsLayer.queryFeatures({\n    where: baseWhere(), returnGeometry: false,\n    outStatistics: [\n      { statisticType: \"percentile-continuous\", onStatisticField: p, outStatisticFieldName: \"p1\", statisticParameters: { value: 0.01 } },\n      { statisticType: \"percentile-continuous\", onStatisticField: p, outStatisticFieldName: \"p99\", statisticParameters: { value: 0.99 } },\n      { statisticType: \"count\", onStatisticField: p, outStatisticFieldName: \"n\" }\n    ]\n  });\n  if (my !== statsSeq) return false;   // a newer choice superseded this one\n  const a = res.features[0]?.attributes || {};\n  const p1 = a.p1 ?? a.P1, p99 = a.p99 ?? a.P99;\n  if (!p1 || !p99 || p99 <= p1) { S.p1 = S.p99 = null; } else { S.p1 = p1; S.p99 = p99; }\n  S.lo = 0; S.hi = STEPS;\n  const sl = $(\"slider\"); sl.minValue = 0; sl.maxValue = STEPS; sl.disabled = S.p1 == null;\n  renderRange();\n  return true;\n}\n\nlet reqId = 0;\nasync function apply() {\n  const my = ++reqId;\n  const where = S.p1 == null ? \"1=0\" : fullWhere();\n  if (highlight) highlight.definitionExpression = where;\n  try {\n    S.countCalls++;\n    const n = await statsLayer.queryFeatureCount({ where });\n    if (my !== reqId) return;\n    S.count = n; S.where = where;\n    $(\"count\").innerHTML = `${n.toLocaleString(\"en-GB\")} <small>building${n === 1 ? \"\" : \"s\"} match</small>`;\n    $(\"status\").textContent = \"\";\n  } catch (e) { S.errors.push(String(e)); $(\"status\").textContent = \"Count query failed: \" + e.message; }\n}\nasync function refreshAll() {\n  let fresh = true;\n  try { fresh = await loadStats(); } catch (e) { S.errors.push(String(e)); $(\"status\").textContent = \"Statistics query failed: \" + e.message; }\n  if (fresh !== false) await apply();\n}\n\nlet tmr;\n$(\"slider\").addEventListener(\"calciteSliderInput\", (ev) => {\n  S.lo = ev.target.minValue; S.hi = ev.target.maxValue; renderRange();\n  clearTimeout(tmr); tmr = setTimeout(apply, 180);\n});\n$(\"slider\").addEventListener(\"calciteSliderChange\", (ev) => { S.lo = ev.target.minValue; S.hi = ev.target.maxValue; renderRange(); clearTimeout(tmr); apply(); });\n$(\"mode\").addEventListener(\"calciteSegmentedControlChange\", (ev) => { S.mode = ev.target.value; refreshAll(); });\n$(\"bed\").addEventListener(\"calciteSegmentedControlChange\", (ev) => { S.bed = +ev.target.value; refreshAll(); });\n$(\"own\").addEventListener(\"calciteSwitchChange\", (ev) => { S.own = ev.target.checked; refreshAll(); });\n$(\"districts\").addEventListener(\"calciteComboboxChange\", (ev) => {\n  S.districts = (ev.target.selectedItems || []).map((i) => i.value); refreshAll();\n});\n$(\"zoom\").addEventListener(\"click\", async () => {\n  if (!view || !S.count) return;\n  try { const r = await statsLayer.queryExtent({ where: S.where || fullWhere() }); if (r.extent) view.goTo(r.extent.expand(1.3)); } catch (e) { S.errors.push(String(e)); }\n});\n\n// District list from the view (slug + display name)\nasync function loadDistricts() {\n  const res = await statsLayer.queryFeatures({\n    where: \"dup_status IS NULL\", returnGeometry: false, groupByFieldsForStatistics: [\"district_slug\", \"district_name\"],\n    outStatistics: [{ statisticType: \"count\", onStatisticField: \"OBJECTID\", outStatisticFieldName: \"n\" }], orderByFields: [\"district_name\"]\n  });\n  const cb = $(\"districts\");\n  for (const f of res.features) {\n    const { district_slug: slug, district_name: name, n } = f.attributes;\n    if (!slug) continue;\n    const it = document.createElement(\"calcite-combobox-item\");\n    it.value = slug; it.heading = name || slug; it.textLabel = name || slug; it.description = `${n.toLocaleString(\"en-GB\")} buildings`;\n    cb.appendChild(it);\n  }\n  S.districtCount = res.features.length;\n}\n\n// Controls first: statistics, counts and districts do not wait for the 3D view (they work even where WebGL is missing).\n(async () => {\n  try { await statsLayer.load(); } catch (e) { S.errors.push(String(e)); $(\"status\").textContent = \"Buildings view failed to load: \" + e.message; return; }\n  const t0 = performance.now();\n  await Promise.all([\n    loadDistricts().catch((e) => { S.errors.push(String(e)); $(\"status\").textContent = \"District list failed: \" + e.message; }),\n    refreshAll()\n  ]);\n  S.firstLoadMs = Math.round(performance.now() - t0);\n  S.ready = true;\n})();\n\n// Scene\nsceneEl = $(\"scene\");\nS.sceneStage = \"waiting for view\";\nawait sceneEl.viewOnReady();\nview = sceneEl.view;\nS.sceneStage = \"view ready\";\nconst map = view.map;\nawait map.loadAll().catch((e) => S.errors.push(\"loadAll: \" + e));\nS.sceneStage = \"layers loaded\";\nconst all = map.allLayers;\nconst carrier = all.find((l) => l.id === CARRIER_ID);\nS.layers = all.map((l) => l.id).toArray();\nS.carrierFound = !!carrier;\n\n// Matching buildings: a gold extrusion 3 m above the model height (so its roof clears the facade roof), drawn over faded context.\nhighlight = new FeatureLayer({\n  url: VIEW_URL, id: \"price_slider_matches\", title: \"Buildings in the price range\",\n  definitionExpression: \"1=0\", outFields: [\"height_m\"],\n  elevationInfo: { mode: \"on-the-ground\" },\n  popupEnabled: true, popupTemplate: carrier?.popupTemplate?.clone() ?? null,\n  renderer: {\n    type: \"simple\",\n    symbol: { type: \"polygon-3d\", symbolLayers: [{ type: \"extrude\", material: { color: [224, 164, 18, 0.92] }, edges: { type: \"solid\", color: [120, 80, 0, 0.6], size: 0.6 } }] },\n    visualVariables: [{ type: \"size\", valueExpression: \"When(IsEmpty($feature.height_m), 15, $feature.height_m + 3)\", valueUnit: \"meters\" }]\n  }\n});\nif (S.where) highlight.definitionExpression = S.where;   // the count may have landed before the scene did\nmap.add(highlight);\n\n// Fade the rest: the scene's own building layers and facades stay as context at low opacity.\nfor (const l of all) {\n  if (CONTEXT_IDS.includes(l.id)) l.opacity = 0.22;\n  if (FACADE_IDS.includes(l.id)) l.opacity = 0.35;\n  if (l.id && l.id.startsWith(\"najma_buildings_ramp_\")) l.visible = false;\n}\n\nS.highlightReady = false;\nview.whenLayerView(highlight).then((lv) => { S.highlightReady = true; reactiveUtils.when(() => !lv.updating, () => { S.lvUpdatingDone = true; }); })\n  .catch((e) => { S.errors.push(\"layerView: \" + e); });\nS.sceneStage = \"highlight added\";\n</script>\n</body>\n</html>\n";
